.hg_contract<-function(raw,context){
 z<-.ex_object(raw,'node contract');if(length(setdiff(names(z),c('unit','target','row_ids','as_of','known_at','currency','feature_order')))) .cr_error('GRAPH_CONTRACT','Unknown contract field');if(!(z$unit%in%c('design','probability','loss_fraction','money'))) .cr_error('GRAPH_UNIT','Unknown node unit');.ex_target(z$target);.ex_ids(z$row_ids,'row_ids')
 for(k in c('as_of','known_at')){.cr_data_date(z[[k]],k);if(!identical(z[[k]],context[[k]])) .cr_error('GRAPH_CONTEXT','All nodes must share immutable dates')};for(k in c('event','horizon','time_unit','probability_measure'))if(!is.null(context[[k]])&&.cr_hash(context[[k]])!=.cr_hash(z$target[[k]])) .cr_error('GRAPH_TARGET','Node target differs from context')
 if(z$unit=='money'){.cr_string(z$currency,'currency','GRAPH_CURRENCY');if(!is.null(context$currency)&&context$currency!=z$currency) .cr_error('GRAPH_CURRENCY','Currency differs from graph context')}else if('currency'%in%names(z)) .cr_error('GRAPH_CURRENCY','Currency only applies to money')
 if(z$unit=='design').ex_ids(z$feature_order,'feature_order',empty=TRUE)else if('feature_order'%in%names(z)) .cr_error('GRAPH_CONTRACT','Feature order only applies to design');if(z$unit%in%c('design','probability')&&!is.null(context$conditioning)&&context$conditioning!=z$target$conditioning) .cr_error('GRAPH_TARGET','PD conditioning differs from graph context');z
}
.hg_value<-function(value,contract){
 if(contract$unit=='design'){features<-.ex_ids(contract$feature_order,'feature_order',empty=TRUE);n<-length(contract$row_ids);if(!length(features)&&is.list(value)&&length(value)==n&&all(lengths(value)==0))x<-matrix(numeric(),n,0)else x<-.ex_matrix(value,'node value');if(!identical(dim(x),c(n,length(features)))) .cr_error('GRAPH_SHAPE','Aligned design dimensions required');return(.ex_rows(x))}
 x<-.ex_vec(value,'node value');if(length(x)!=length(contract$row_ids)) .cr_error('GRAPH_SHAPE','One value per ordered row required');if(contract$unit=='probability'&&any(x<0|x>1)) .cr_error('GRAPH_PROBABILITY','Probability outside domain');as.list(x)
}
.hg_ports<-function(inputs,expected){if(!setequal(names(inputs),expected)) .cr_error('GRAPH_PORT','Operation requires exact input ports')}
.hg_same<-function(a,b,conditioning=TRUE){for(k in c('unit','feature_order','currency')){a[[k]]<-NULL;b[[k]]<-NULL};if(!conditioning){a$target$conditioning<-NULL;b$target$conditioning<-NULL};if(.cr_hash(a)!=.cr_hash(b)) .cr_error('GRAPH_ALIGNMENT','Rows, dates, targets or conditioning differ')}
evaluate_model_graph<-function(model_graph,input_data,parameter_snapshots,context){
 graph<-.ex_object(model_graph,'model_graph');data<-.ex_object(input_data,'input_data');snapshots<-.ex_object(parameter_snapshots,'parameter_snapshots');ctx<-.cr_result(NULL,'hybrid.context',context=context)$context
 if(!identical(ctx$mode,'DATED')||.cr_data_date(ctx$known_at,'known_at')>.cr_data_date(ctx$as_of,'as_of')) .cr_error('GRAPH_CONTEXT','Dated non-lookahead context required');for(k in c('graph_id','graph_version')).cr_string(graph[[k]],k,'GRAPH_CONTRACT');nodes<-.hy_rows(graph$nodes,'nodes');ids<-.ex_ids(lapply(nodes,function(n)n$node_id),'node_ids');names(nodes)<-ids;output<-graph$output_node;if(!(output%in%ids)) .cr_error('GRAPH_CONTRACT','Unknown output node')
 for(n in nodes){inputs<-.ex_object(n$inputs,'inputs');.ex_object(n$parameters,'parameters');.hg_contract(n$output_contract,ctx);if(length(setdiff(unlist(inputs),ids))) .cr_error('GRAPH_EDGE','Unknown parent node')}
 order<-character();remaining<-ids;while(length(remaining)){ready<-sort(remaining[vapply(remaining,function(i)all(unlist(nodes[[i]]$inputs)%in%order),logical(1))]);if(!length(ready)) .cr_error('GRAPH_CYCLE','Acyclic execution graph required');order<-c(order,ready);remaining<-setdiff(remaining,ready)}
 results<-structure(list(),names=character());trace<-list();cache<-new.env(parent=emptyenv())
 for(node_id in order){node<-nodes[[node_id]];op<-node$operation;params<-node$parameters;parents<-.ex_object(lapply(.ex_object(node$inputs,'inputs'),function(i)results[[i]]),'parents');declared<-.hg_contract(node$output_contract,ctx);effects<-sort(unique(as.character(unlist(lapply(parents,function(p)p$effects)))));new_effect<-NULL;snapshot<-NULL
 allowed<-list(input='input_id',predict_pd='snapshot_id',apply_calibrator=c('snapshot_id','base_model_version','groups'),combine_pd_signals=c('signal_order','weights','combination_scale','combination_contract'),log_odds_shift=c('shift','effect_id','reference'),expected_loss=c('loss_assumption','reference'));if(!(op%in%names(allowed))||length(setdiff(names(params),allowed[[op]]))) .cr_error('GRAPH_OPERATION','Unsupported operation or parameter')
 if(op%in%c('predict_pd','apply_calibrator')){snapshot<-snapshots[[params$snapshot_id]];if(is.null(snapshot)) .cr_error('GRAPH_SNAPSHOT','Missing frozen parameter snapshot')}
 key<-.cr_hash(list(operation=op,parameters=params,parents=parents,declared_contract=declared,snapshot=snapshot,context=ctx,input_snapshot=if(op=='input')data[[params$input_id]]else NULL));cached<-exists(key,envir=cache,inherits=FALSE)
 if(cached)result<-get(key,envir=cache,inherits=FALSE)else{
 if(op=='input'){
 .hg_ports(parents,character());record<-.ex_object(data[[params$input_id]],'input snapshot');contract<-.hg_contract(record$contract,ctx);value<-.hg_value(record$value,contract);if(!is.null(record$effects))effects<-.ex_ids(record$effects,'input effects',empty=TRUE)
 }else if(op=='predict_pd'){
 .hg_ports(parents,'design');parent<-parents$design;contract<-parent$contract;if(contract$unit!='design') .cr_error('GRAPH_UNIT','Model requires design input');model<-.cr_model(snapshot);if(.cr_data_date(model$training$known_at,'model known_at')>.cr_data_date(ctx$known_at,'known_at')) .cr_error('GRAPH_LOOKAHEAD','Model unavailable at cutoff');features<-.ex_ids(contract$feature_order,'feature_order',empty=TRUE);design<-if(!length(features))matrix(numeric(),length(contract$row_ids),0)else .ex_matrix(parent$value,'design');value<-predict_pd(model,design,feature_order=features,expected_target=contract$target,context=ctx)$value;contract$feature_order<-NULL;contract$unit<-'probability'
 }else if(op=='apply_calibrator'){
 .hg_ports(parents,'pd');parent<-parents$pd;contract<-parent$contract;if(contract$unit!='probability') .cr_error('GRAPH_UNIT','Calibrator requires probabilities');if(!(snapshot$calibration_type%in%c('intercept','logistic','isotonic','beta','hierarchical'))) .cr_error('GRAPH_UNIT','Only PD calibrators are allowed');if(.cr_data_date(snapshot$metadata$calibration$known_at,'calibration known_at')>.cr_data_date(ctx$known_at,'known_at')) .cr_error('GRAPH_LOOKAHEAD','Calibrator unavailable at cutoff');new_effect<-paste0('calibration:',snapshot$artifact_hash);value<-apply_calibrator(snapshot,.ex_vec(parent$value,'pd'),target=contract$target,base_model_version=params$base_model_version,groups=params$groups,context=ctx)$value
 }else if(op=='combine_pd_signals'){
 ports<-.ex_ids(params$signal_order,'signal_order');.hg_ports(parents,ports);contract<-parents[[ports[1]]]$contract;signals<-lapply(ports,function(port){parent<-parents[[port]];.hg_same(contract,parent$contract);if(parent$contract$unit!='probability') .cr_error('GRAPH_UNIT','Only probabilities may be pooled');list(signal_id=port,model_id=port,model_version=.cr_hash(parent),row_ids=contract$row_ids,target=contract$target,as_of=contract$as_of,known_at=contract$known_at,pd=parent$value)});value<-combine_pd_signals(signals,params$weights,combination_scale=params$combination_scale,combination_contract=params$combination_contract,context=ctx)$value$pd
 }else if(op=='log_odds_shift'){
 .hg_ports(parents,'pd');parent<-parents$pd;contract<-parent$contract;if(contract$unit!='probability') .cr_error('GRAPH_UNIT','Log-odds adjustment requires probabilities');shift<-.ex_vec(params$shift,'shift');p<-.ex_vec(parent$value,'pd');if(length(shift)!=length(p)) .cr_error('GRAPH_SHAPE','Aligned shifts required');for(k in c('effect_id','reference')).cr_string(params[[k]],k,'GRAPH_ADJUSTMENT');new_effect<-params$effect_id;value<-p;inside<-p>0&p<1;value[inside]<-stats::plogis(stats::qlogis(p[inside])+shift[inside])
 }else if(op=='expected_loss'){
 .hg_ports(parents,c('pd','lgd','ead'));pd<-parents$pd;lgd<-parents$lgd;ead<-parents$ead;contract<-pd$contract;if(!identical(vapply(list(pd,lgd,ead),function(p)p$contract$unit,character(1)),c('probability','loss_fraction','money'))) .cr_error('GRAPH_UNIT','Expected loss requires probability, fraction and money');.hg_same(contract,lgd$contract,FALSE);.hg_same(contract,ead$contract,FALSE)
 if(contract$target$conditioning!='performing'||lgd$contract$target$conditioning!='default'||ead$contract$target$conditioning!='default') .cr_error('GRAPH_CONDITIONING','Performing PD and default-conditional LGD/EAD required');if(!(params$loss_assumption%in%c('deterministic_conditional_amounts','conditional_independence_EAD_LGD'))) .cr_error('GRAPH_LOSS_ASSUMPTION','Explicit conditional product assumption required');.cr_string(params$reference,'reference','GRAPH_LOSS_ASSUMPTION');seen<-character();for(parent in list(pd,lgd,ead)){if(length(intersect(seen,unlist(parent$effects)))) .cr_error('GRAPH_DOUBLE_COUNT','Same effect on several loss legs');seen<-union(seen,unlist(parent$effects))};if(any(.ex_vec(ead$value,'ead')<0)) .cr_error('GRAPH_EAD','EAD cannot be negative');value<-expected_loss(.ex_vec(pd$value,'pd'),.ex_vec(lgd$value,'lgd'),.ex_vec(ead$value,'ead'),context=ctx)$value;contract$unit<-'money';contract$currency<-ead$contract$currency
 }else .cr_error('GRAPH_OPERATION','Unsupported operation')
 if(!is.null(new_effect)){if(new_effect%in%effects) .cr_error('GRAPH_DOUBLE_COUNT','Effect already applied in ancestry');effects<-sort(c(effects,new_effect))};if(.cr_hash(contract)!=.cr_hash(declared)) .cr_error('GRAPH_CONTRACT','Computed output differs from declared contract');result<-list(value=.hg_value(value,contract),contract=contract,effects=as.list(effects));assign(key,result,envir=cache)
 };results[[node_id]]<-result;trace[[length(trace)+1L]]<-list(node_id=node_id,operation=op,inputs=node$inputs,cache_key=key,cache_hit=cached,result=result)
 }
 value<-.ex_seal(list(schema_version='1.0',graph=graph,input_snapshots=data,parameter_snapshots=snapshots,context=ctx,node_results=results,trace=trace,output_node=output,final=results[[output]]),'result_hash');.cr_result(value,'hybrid.evaluate_model_graph',results[[output]]$contract$unit,ctx,diagnostics=list(node_count=length(nodes),unique_computations=length(ls(cache)),cache_hits=length(nodes)-length(ls(cache))),limitations='Frozen operations only; declared provenance and hashes do not authenticate evidence. Cyclic financial models require an explicit domain solver outside this execution graph.')
}
decompose_hybrid_prediction<-function(hybrid_result,baseline_inputs,decomposition_scale='native',context=NULL){
 result<-.ex_read(hybrid_result,'result_hash');ctx<-result$context;if(!is.null(context)&&.cr_hash(.cr_result(NULL,'hybrid.context',context=context)$context)!=.cr_hash(ctx)) .cr_error('GRAPH_CONTEXT','Original immutable context required');baseline<-.ex_object(baseline_inputs,'baseline_inputs');actual<-result$input_snapshots;if(!setequal(names(baseline),names(actual))) .cr_error('GRAPH_BASELINE','Exactly the frozen input snapshots required');for(name in names(actual))if(.cr_hash(baseline[[name]]$contract)!=.cr_hash(actual[[name]]$contract)||.cr_hash(baseline[[name]]$effects)!=.cr_hash(actual[[name]]$effects)) .cr_error('GRAPH_BASELINE','Baseline may change values only')
 if(result$final$contract$unit=='design') .cr_error('GRAPH_DECOMPOSITION','Final output cannot be a design');if(!(decomposition_scale%in%c('native','log_odds'))) .cr_error('GRAPH_DECOMPOSITION','Use native or log_odds scale');if(decomposition_scale=='log_odds'&&result$final$contract$unit!='probability') .cr_error('GRAPH_UNIT','Log odds requires PD output')
 replay<-function(data)evaluate_model_graph(result$graph,data,result$parameter_snapshots,context=ctx)$value;transform<-function(value){x<-.ex_vec(value,'value');if(decomposition_scale=='log_odds'){if(any(x<=0|x>=1)) .cr_error('GRAPH_BOUNDARY','Interior outputs required for finite log odds');x<-stats::qlogis(x)};x}
 verified<-replay(actual);for(name in names(result$node_results)){node<-result$node_results[[name]];check<-verified$node_results[[name]];a<-as.numeric(unlist(node$value));b<-as.numeric(unlist(check$value));if(is.null(check)||.cr_hash(check$contract)!=.cr_hash(node$contract)||.cr_hash(check$effects)!=.cr_hash(node$effects)||length(a)!=length(b)||any(abs(a-b)>1e-14+1e-12*abs(a))) .cr_error('GRAPH_REPLAY','Frozen graph does not reproduce node values and contracts')};if(.cr_hash(result$final)!=.cr_hash(result$node_results[[result$output_node]])) .cr_error('GRAPH_REPLAY','Final differs from output node');if(length(result$trace)!=length(verified$trace)) .cr_error('GRAPH_REPLAY','Trace length differs from graph');for(i in seq_along(result$trace)){step<-result$trace[[i]];check<-verified$trace[[i]];if(any(vapply(c('node_id','operation','inputs'),function(k).cr_hash(step[[k]])!=.cr_hash(check[[k]]),logical(1)))||.cr_hash(step$result)!=.cr_hash(result$node_results[[check$node_id]])) .cr_error('GRAPH_REPLAY','Trace differs from graph node results')};base<-replay(baseline);a<-transform(result$final$value);b<-transform(base$final$value);total<-rep(0,length(a));contributions<-list();for(name in sort(names(actual))){one<-baseline;one[[name]]<-actual[[name]];change<-transform(replay(one)$final$value)-b;total<-total+change;contributions[[length(contributions)+1L]]<-list(input_id=name,contribution=as.list(change))};remainder<-a-b-total
 steps<-lapply(result$trace,function(step){parents<-lapply(step$inputs,function(p)result$node_results[[p]]);out<-step$result;delta<-NULL;if(length(parents)==1L&&.cr_hash(parents[[1]]$contract)==.cr_hash(out$contract))delta<-as.list(.ex_vec(out$value,'out')-.ex_vec(parents[[1]]$value,'parent'));list(node_id=step$node_id,operation=step$operation,unit=out$contract$unit,output=out$value,local_native_delta=delta,additive_global_contribution=FALSE)})
 .cr_result(list(baseline=as.list(b),actual=as.list(a),input_contributions=contributions,interaction_remainder=as.list(remainder),reconstructed=as.list(b+total+remainder),reconciliation_error=as.list(a-(b+total+remainder)),decomposition_scale=decomposition_scale,steps=steps,graph_result_hash=result$result_hash,baseline_result_hash=base$result_hash,attribution='ONE_INPUT_AT_A_TIME_FROM_COMMON_BASELINE_WITH_EXPLICIT_INTERACTION_REMAINDER'),'hybrid.decompose_hybrid_prediction',if(decomposition_scale=='log_odds')'log_odds'else result$final$contract$unit,ctx,limitations='Reference changes are not causal effects or Shapley values. Interactions remain explicit; local step deltas must not be summed across branches.')
}
